        private void CheckForUnionMemberErrors(BindingDiagnosticBag diagnostics)
        {
            if (!IsUnion)
            {
                return;
            }

            foreach (var member in GetMembersAndInitializers().NonTypeMembers)
            {
                switch (member)
                {
                    case FieldSymbol { IsStatic: false, AssociatedSymbol: null } field:
                        // An explicitly declared instance field. Backing fields of properties or events have an
                        // associated symbol and are reported (once) through that property or event instead.
